def tri(n):
    if n == 0:
        return [1]

    seq = [1]  # index 0
    seq.append(3)  # index 1, tri(1) = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            seq.append(1 + i // 2)
        else:
            # i is odd and > 1, so i+1 is even
            seq.append(seq[i - 1] + seq[i - 2] + (1 + (i + 1) // 2))

    return seq
